// ---- build what the games use: VOCAB[world].words = [[art, es, pic, en (, 'f')], ...] and RIDDLES[pic] ----
const VOCAB = {}, RIDDLES = {}, WORD_BY_PIC = {};
for (const [k, meta] of Object.entries(WORLDS)) VOCAB[k] = { ...meta, words: [] };
for (const x of WORDS) {
  if (WORD_BY_PIC[x.pic]) console.warn('Palabras: picture used twice', x.pic);
  if (!VOCAB[x.world]) { console.warn('Palabras: unknown world', x.world, x.es); continue; }
  if (!x.riddle) console.warn('Palabras: no riddle yet for', x.es);
  WORD_BY_PIC[x.pic] = x;
  VOCAB[x.world].words.push(x.elFem ? [x.art, x.es, x.pic, x.en, 'f'] : [x.art, x.es, x.pic, x.en]);
  if (x.riddle) RIDDLES[x.pic] = x.riddle;
}
function uniq(ws){ const seen=new Set(); return ws.filter(w=>!seen.has(w[2]) && seen.add(w[2])); }
VOCAB.todos.words = uniq(Object.values(VOCAB).filter(c=>c.animal).flatMap(c=>c.words));
VOCAB.todas.words = uniq(Object.entries(VOCAB).filter(([k])=>k!=='todos'&&k!=='todas').flatMap(([,c])=>c.words));

